{"code": "import pandas as pd, numpy as np
df = pd.read_csv('data/explore.csv')
expos = ['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
c = df[expos].corr()
np.set_printoptions(precision=2, suppress=True, linewidth=200)
print(c)
# high correlations
for i in range(len(expos)):
    for j in range(i+1,len(expos)):
        if abs(c.iloc[i,j])>0.3:
            print(expos[i], expos[j], round(c.iloc[i,j],3))
"}
